def apply_replaces(text, replaces):
    out = text
    for old, new in replaces.items():
        if old in out:
            out = out.replace(old, new, 1)
    return out


def make_variant(base_template, sex, sex_zh, sex_en, replaces, default_replace_sex_text, tags_suffix):
    """Clone a base template and apply sex-specific replacements."""
    t = OrderedDict(base_template)
    # Update id / name / name_en / description / tags / preview
    t["id"] = base_template["id"] + "_" + sex
    t["name"] = base_template["name"].replace("\u533b\u7528\u4eba\u4f53\u00b7", "\u533b\u7528\u4eba\u4f53\u00b7" + sex_zh + "\u00b7")
    t["name_en"] = sex_en + base_template["name_en"].replace("Medical ", "")
    t["description"] = "\u3010" + sex_zh + "\u7248\u3011" + base_template["description"]
    t["preview"] = base_template["preview"].replace(".webp", "_" + sex + ".webp")
    t["tags"] = list(base_template["tags"]) + tags_suffix
    # Apply prompt replaces
    t["prompt"] = apply_replaces(base_template["prompt"], replaces)
    # Add the sex tag to the prompt
    t["prompt"] = ("[STRICT SEX / \u4e25\u683c\u6027\u522b\u58f0\u660e]: \u672c\u6a21\u677f\u4e3a\u3010" + sex_zh + "\u4eba\u4f53\u3011\u4e13\u7528\u3002\u5fc3\u91cd/\u80be\u91cd/\u8840\u7ea2\u86cb\u767d/\u9aa8\u76d6\u5f62\u6001/\u751f\u6b96\u7cfb\u7edf/\u808c\u91cf\u4e0e\u4f53\u8102/\u4e94\u5b98\u4e0e\u4e73\u623f/\u4f53\u6bdb\u5206\u5e03/\u80a1\u4e0a\u4e0a\u80a1\u4e0a\u80a1/\u80a1\u8089/\u4e73\u4e73\u593e\u4e0a/\u4e73\u4e73\u593e\u4e0a\u80a1\u3001\u9ed8\u8ba4\u7537\u4eba 175cm/70kg\uff0c\u5973\u4eba 165cm/57kg\u3002 \u4e0d\u8981\u6df7\u7528\u5bf9\u65b9\u6027\u522b\u4eba\u4f53\u53c2\u6570\u3002\n\n"
                   + t["prompt"])
    # Update text_fallback_prompt
    t["text_fallback_prompt"] = default_replace_sex_text + base_template["text_fallback_prompt"]
    # Update text_fallback_mode
    t["text_fallback_mode"] = "Text to Video (\u6587\u751f\u89c6\u9891)\u3010\u9ed8\u8ba4" + sex_zh + "\u4eba\u4f53\u56fe\u8c31\u3011"
    return t


def make_subcategory(sex, sex_zh, sex_en, sub_id, base_subcat):
    """Build a subcategory of 6 sex-specific templates."""
    replaces_map = {
        "male": {
            "med_full_body_anatomy": OrderedDict(),
            "med_skeletal_system": MALE_SKELETAL_REPLACE,
            "med_muscular_system": MALE_MUSCLE_REPLACE,
            "med_organ_systems": MALE_ORGANS_REPLACE,
            "med_face_features_closeup": MALE_FACE_REPLACE,
            "med_hands_feet_skin": MALE_HFS_REPLACE,
        },
        "female": {
            "med_full_body_anatomy": OrderedDict(),
            "med_skeletal_system": FEMALE_SKELETAL_REPLACE,
            "med_muscular_system": FEMALE_MUSCLE_REPLACE,
            "med_organ_systems": FEMALE_ORGANS_REPLACE,
            "med_face_features_closeup": FEMALE_FACE_REPLACE,
            "med_hands_feet_skin": FEMALE_HFS_REPLACE,
        },
    }[sex]
    default_sex_prefix = {
        "male": ("[STRICT DEFAULT SEX / \u9ed8\u8ba4\u6027\u522b\u58f0\u660e]: \u672c\u6a21\u677f\u9ed8\u8ba4\u4e3a\u3010\u7537\u6027\u3011\u4eba\u4f53\u56fe\u8c31\uff08\u9ed8\u8ba4 25 \u5c81 / 175cm / 70kg / \u4f53\u8102 15% / \u808c\u91cf ~35kg / \u8840\u7ea2\u86cb\u767d 13-17 g/dL / \u9aa8\u76d6\u5fc3\u5f62\uff09\u3002\n\n"),
        "female": ("[STRICT DEFAULT SEX / \u9ed8\u8ba4\u6027\u522b\u58f0\u660e]: \u672c\u6a21\u677f\u9ed8\u8ba4\u4e3a\u3010\u5973\u6027\u3011\u4eba\u4f53\u56fe\u8c31\uff08\u9ed8\u8ba4 25 \u5c81 / 165cm / 57kg / \u4f53\u8102 25% / \u808c\u91cf ~24kg / \u8840\u7ea2\u86cb\u767d 12-15 g/dL / \u9aa8\u76d6\u692d\u5706\uff09\u3002\n\n"),
    }[sex]
    tags_suffix = {
        "male": ["\u7537\u6027", "\u7537\u4eba\u4f53"],
        "female": ["\u5973\u6027", "\u5973\u4eba\u4f53"],
    }[sex]
    new_templates = []
    for base in base_subcat["templates"]:
        tid = base["id"]
        replaces = replaces_map.get(tid, OrderedDict())
        # Also patch the sex tail in full body
        if tid == "med_full_body_anatomy":
            # The MALE_FB_TAIL / FEMALE_FB_TAIL replace the existing 9-system text
            tail_old = "\u3002\u672c\u6bb5\u4ee5\u300c\u4e5d\u5927\u7cfb\u7edf\u300d\u2014\u2014\u6d88\u5316\u3001\u547c\u5438\u3001\u5faa\u73af\u3001\u6ccc\u5c3f\u3001\u751f\u6b96\u3001\u5185\u5206\u6ccc\u3001\u795e\u7ecf\u3001\u514d\u75ab\uff08\u6dcb\u5df4\uff09\u4e0e\u76ae\u80a4\u2014\u2014\u4e3a\u4e3b\u7ebf\u67b6\u6784\uff0c\u4e0e\u808c\u8089\u3001\u9aa8\u9abc\u3001\u795e\u7ecf\u8840\u7ba1\u4e92\u4e3a\u8865\u5145\uff0c\u67b6\u8d77\u5b8c\u6574\u4eba\u4f53\u4e09\u7ef4\u89e3\u5256\u3002"
            tail_new = MALE_FB_TAIL if sex == "male" else FEMALE_FB_TAIL
            if tail_old in base["prompt"]:
                base_copy = OrderedDict(base)
                base_copy["prompt"] = base["prompt"].replace(tail_old, tail_new, 1)
                base = base_copy
        new_t = make_variant(base, sex, sex_zh, sex_en, replaces, default_sex_prefix, tags_suffix)
        new_templates.append(new_t)
    new_sub = OrderedDict([
        ("id", sub_id),
        ("name", "\u533b\u7528\u4eba\u4f53\u00b7" + sex_zh),
        ("name_en", "Medical Human Anatomy - " + sex_en),
        ("description",
         "\u3010" + sex_zh + "\u4eba\u4f53\u3011\u533b\u7528\u4eba\u4f53\u7ed3\u6784\u56fe\u8c31\u6a21\u677f\u3002" + ("\u9ed8\u8ba4 25 \u5c81 / 175cm / 70kg / \u4f53\u8102 15% / \u808c\u91cf ~35kg / \u8840\u7ea2\u86cb\u767d 13-17 g/dL / \u9aa8\u76d6\u5fc3\u5f62 / \u5fc3\u91cd ~300g / \u80be\u91cd ~150g\u3002" if sex == "male" else
          "\u9ed8\u8ba4 25 \u5c81 / 165cm / 57kg / \u4f53\u8102 25% / \u808c\u91cf ~24kg / \u8840\u7ea2\u86cb\u767d 12-15 g/dL / \u9aa8\u76d6\u692d\u5706 / \u5fc3\u91cd ~260g / \u80be\u91cd ~135g\u3002") + "\n"
         "6 \u4e2a\u6a21\u677f\uff1a\u5168\u8eab\u89e3\u5256\u56fe\u8c31 / \u9aa8\u9abc\u7cfb\u7edf 206 \u5757 / \u808c\u8089\u7cfb\u7edf ~640 \u5757 / \u4e5d\u5927\u7cfb\u7edf\u5185\u810f / \u4e94\u5b98\u7cbe\u7ec6\u89e3\u5256 / \u624b\u811a\u76ae\u80a4\u6bdb\u56ca\u7ec4\u7ec7\u3002"
         "\u53c2\u8003\u56fe\u8f93\u5165\u987a\u5e8f\uff1a\u56fe1=\u4eba\u7269\u6574\u4f53\uff08\u5fc5\u9009\uff0c\u9700\u4e0e\u672c\u6a21\u677f\u6027\u522b\u4e00\u81f4\uff09\uff0c\u56fe2=\u53ef\u9009\u67d0\u5c40\u90e8/\u5668\u5b98\u7279\u5199\uff08\u6309\u9700\u63d0\u4f9b\uff09\u3002"),
        ("templates", new_templates),
    ])
    return new_sub


def process(fp):
    with open(fp, "r", encoding="utf-8") as f:
        d = json.load(f)
    for cat in d["categories"]:
        if cat.get("id") == "xray_scan":
            sub_ids = [s.get("id") for s in cat.get("subcategories", [])]
            if "medical_anatomy" not in sub_ids:
                print("  medical_anatomy not found in", fp)
                return
            # Get base subcategory
            base_subcat = None
            for s in cat["subcategories"]:
                if s["id"] == "medical_anatomy":
                    base_subcat = s
                    break
            # Build two new subcategories
            male_sub = make_subcategory("male", "\u7537\u6027", "Male ", "medical_anatomy_male", base_subcat)
            female_sub = make_subcategory("female", "\u5973\u6027", "Female ", "medical_anatomy_female", base_subcat)
            # Remove old, append new
            new_subs = [s for s in cat["subcategories"] if s["id"] != "medical_anatomy"]
            new_subs.append(male_sub)
            new_subs.append(female_sub)
            cat["subcategories"] = new_subs
            # Update top description
            cat["description"] = (
                "\u533b\u5b66\u900f\u89c6\u626b\u63cf + \u533b\u7528\u4eba\u4f53\u7ed3\u6784\u677f\u5757\uff1a"
                "\u624b\u6301\u626b\u63cf\u8bbe\u5907\u626b\u8fc7\u4eba\u7269\u6216\u7269\u4f53\u663e\u793a\u5185\u90e8\u7ed3\u6784(\u9aa8\u9abc/\u5185\u810f)\uff0c"
                "\u6216\u76f4\u63a5\u8f93\u51fa\u533b\u7528\u4eba\u4f53\u56fe\u8c31 3D \u6e32\u67d3\u2014\u2014\u9aa8\u9abc/\u808c\u8089/\u5185\u810f/\u795e\u7ecf\u8840\u7ba1/\u4e94\u5b98/\u624b\u811a/\u76ae\u80a4/\u7ec4\u7ec7\u5207\u7247\u5168\u5957\u4e2d\u82f1\u53cc\u8bed\u89e3\u5256\u6807\u6ce8\uff0c"
                "\u533b\u7528\u4eba\u4f53\u7ed3\u6784\u62c6\u5206\u4e3a\u7537\u6027/\u5973\u6027\u4e24\u4e2a\u72ec\u7acb\u5b50\u5206\u7c7b\uff0c\u5404 6 \u4e2a\u6a21\u677f\u3002"
            )
    with open(fp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print("SPLIT DONE:", fp)


